# Hypothesis: A_i = A_shared + dA_i; the task-specific reading is in dA_i, the cross-talk carrier is B_i A_shared.
import torch, time, collections, json
t0 = time.time()
LEAVES = list(TARGET_LEAVES)
def fro(B, A):
    return float(torch.sqrt(torch.clamp(torch.trace((B.T @ B) @ (A @ A.T)), min=0)))
STATS = {}
for m in MODULES:
    As, Bs = {}, {}
    for a in ADAPTER_NAMES:
        A, B, alpha, r = lora(a, m); As[a] = A * (alpha / r); Bs[a] = B
    Ash = torch.stack([As[a] for a in ADAPTER_NAMES]).mean(0)
    for a in ADAPTER_NAMES:
        dA = As[a] - Ash
        cosA = float(torch.nn.functional.cosine_similarity(As[a].flatten(), Ash.flatten(), dim=0))
        STATS[(a, m)] = dict(full=fro(Bs[a], As[a]), sh=fro(Bs[a], Ash), d=fro(Bs[a], dA), cosA=cosA,
                             nA=float(As[a].norm()), ndA=float(dA.norm()), nB=float(Bs[a].norm()))
