# Hypothesis: B_m dA_m holds mnist's skill; B_m A_shared is cross-talk. Variant D1: mnist A -> dA (median-shared), others plain.
import torch
def scaled(a, m):
    A, B, alpha, r = lora(a, m); return A * (alpha / r), B
def shared_A(m, how="median"):
    As = torch.stack([scaled(a, m)[0] for a in ADAPTER_NAMES])
    return As.median(0).values if how == "median" else As.mean(0)
def build(spec):
    # spec: {adapter: {"w": float or {leaf: float} or {layer-leaf fn}, "mode": "full" | "dA" | "mix", "lam": float}}
    for m in MODULES:
        Ash = shared_A(m)
        As, Bs = [], []
        for a, s in spec.items():
            A, B = scaled(a, m)
            w = s.get("w", 1.0)
            if callable(w): w = w(m)
            elif isinstance(w, dict): w = w.get(m.split(".")[-1], 1.0)
            if w == 0: continue
            mode = s.get("mode", "full")
            if mode == "dA": A = A - Ash
            elif mode == "mix": A = Ash + s.get("lam", 1.0) * (A - Ash)
            As.append(w * A); Bs.append(B)
        set_lora(m, torch.cat(As, 0), torch.cat(Bs, 1))
