# C5: C1 + "mix" amplification for the victims: A_banking, A_disfl -> A_sh + 2 dA (own-input reading doubled), then P2 blinding, C1 weights.
import torch, time
t0 = time.time()
def build_P(k=16, kown=None, spec_w=None, protect=True, stats=None, lam=None):
    kown = kown or k; lam = lam or {}
    for m in MODULES:
        As, Bs, Vs, Vown = {}, {}, {}, {}
        for a in ADAPTER_NAMES:
            A, B = scaled(a, m); Bs[a] = B
            d = A - ASH[m]
            U, S, Vh = torch.linalg.svd(d, full_matrices=False)
            Vs[a] = Vh[:k].T; Vown[a] = Vh[:kown].T
            As[a] = ASH[m] + lam.get(a, 1.0) * d
        for a in ADAPTER_NAMES:
            Uo = torch.cat([Vs[b] for b in ADAPTER_NAMES if b != a], 1)
            if protect: Uo = Uo - Vown[a] @ (Vown[a].T @ Uo)
            Q, R = torch.linalg.qr(Uo); Q = Q[:, R.diagonal().abs() > 1e-3]
            A = As[a]; proj = (A @ Q) @ Q.T
            if stats is not None: stats[a].append(float(proj.norm() / A.norm()))
            w = 1.0 if spec_w is None else spec_w(a, m)
            As[a] = w * (A - proj)
        set_lora(m, torch.cat([As[a] for a in ADAPTER_NAMES], 0), torch.cat([Bs[a] for a in ADAPTER_NAMES], 1))
